package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and a grade (A, B or C), dated: each grade is in force from its from-date. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded for the person; the first given has no from-date (from the beginning of time). */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's holds: their open claims dated within one, and not bound by a statement, count in no live
     *  total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** The other names the person is found by, stored trimmed. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias", nullable = false)
    private Set<String> aliases = new HashSet<>();

    /** Raised on every save; an edit made from an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(null, grade));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, in the order they take effect. */
    public List<GradeFrom> getGrades() {
        return grades.stream().sorted(GradeFrom.BY_FROM).toList();
    }

    /** The grade in force on {@code date}: the one with the latest from-date on or before it. A null date
     *  takes the latest grade recorded. */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> date == null || g.getFromDate() == null || !g.getFromDate().isAfter(date))
                .max(GradeFrom.BY_FROM)
                .orElseGet(() -> grades.stream().min(GradeFrom.BY_FROM).orElseThrow())
                .getGrade();
    }

    /** Record {@code grade} from {@code from}, replacing the grade recorded from that same date, if any. */
    public void setGradeFrom(LocalDate from, String grade) {
        grades.removeIf(g -> Objects.equals(g.getFromDate(), from));
        grades.add(new GradeFrom(from, grade));
    }

    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    /** The person's aliases, sorted as names are compared: without regard to case. */
    public List<String> getAliases() {
        return aliases.stream().sorted(String.CASE_INSENSITIVE_ORDER).toList();
    }

    public void addAlias(String alias) {
        aliases.add(alias);
    }

    public long getVersion() {
        return version;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Retired as soon as a retirement date is set, whatever the date. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The holds recorded, in the order they start. */
    public List<Hold> getHolds() {
        return holds.stream().sorted(Hold.BY_FROM).toList();
    }

    public void addHold(Hold hold) {
        holds.add(hold);
    }

    /** Whether a claim of this person counts in the live totals on the sheet's {@code today}: an OPEN or PENDING one
     *  dated within a hold, or any once {@code today} reaches the retirement date, does not, unless a statement
     *  binds it. */
    public boolean counts(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts in the figures of a period ending {@code end}: by the status it had at
     *  the end of that day, left out when held or retired as the live totals on the sheet's {@code today} say. */
    public boolean countsAtEnd(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus at = claim.statusAt(end);
        return at != null && at.counts() && (claim.isStated() || !heldOn(claim, today));
    }

    /** Whether a claim of this person counts when no statement binds it, as a new statement finds it. */
    public boolean countsUnbound(Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !heldOn(claim, today);
    }

    /** Whether the claim is open and dated within one of the person's holds, or open once {@code today} reaches
     *  the person's retirement date. */
    private boolean heldOn(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen()
                && (retiredOn(today) || holds.stream().anyMatch(h -> h.covers(claim.getDate())));
    }

    /** Whether the retirement date is reached on {@code date}: set, and on or before it. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date != null && !date.isBefore(retiredFrom);
    }

    /** Whether a claim dated {@code date} is refused: one dated after the retirement date. */
    public boolean refusesClaimOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people kept on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;
    private final Rollup rollup;

    public PersonService(PersonRepository people, SheetService sheets, Audit audit, Rollup rollup) {
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** Everyone on the sheet, in the order they were added. */
    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a person on no terms of their own. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        return add(sheetId, user, name, grade, null);
    }

    /** Add a person with their own terms (null: none); the name is stored trimmed and must not already be in use
     *  on the sheet. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms) {
        return add(sheetId, user, name, grade, terms, null);
    }

    /** Add a person with their own terms (null: none) and contact (stored trimmed and lower-cased; blank or null:
     *  none); the name and the contact must not already be in use on the sheet. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)
                || people.findBySheetIdAndAliasIgnoreCase(sheetId, trimmed).isPresent()) {
            throw nameInUse();
        }
        String reach = contactOf(contact);
        if (reach != null && people.existsBySheetIdAndContact(sheetId, reach)) {
            throw contactInUse();
        }
        Rollup.Figures before = rollup.of(sheetId);
        Person person = new Person(sheetId, trimmed, grade);
        person.setTerms(terms);
        person.setContact(reach);
        Person added = save(person);
        audit.recordChangeOnCommit(sheetId, user, entry("PERSON_ADDED", user, added, grade)
                + (terms != null ? " terms=" + terms : "") + (reach != null ? " contact=" + reach : ""));
        rollup.recordChanges(sheetId, user, before);
        return added;
    }

    /** The sheet's today, or null for a sheet never loaded. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.today(sheetId);
    }

    /**
     * Edit a person, as loaded at {@code version}: refused when someone has saved them since. The grade is
     * recorded from {@code gradeFrom} (null: the sheet's today), keeping the grades already recorded from
     * other dates; a save leaving the grade as in force on the sheet's today, with no from-date, records none.
     * The person's own terms become {@code terms} (null: none); their contact is kept.
     */
    @Transactional
    public Person update(String sheetId, String user, long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        return update(sheetId, user, id, version, name, grade, gradeFrom, terms, person.getContact());
    }

    /**
     * Edit a person as {@link #update(String, String, long, long, String, String, LocalDate, Integer)} does, their
     * contact becoming {@code contact} (stored trimmed and lower-cased; blank or null: none): refused when another
     * person on the sheet has it.
     */
    @Transactional
    public Person update(String sheetId, String user, long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        LocalDate today = sheets.load(sheetId, user).getToday();
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        if (person.getVersion() != version) {
            throw changedSince();
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)
                || people.findBySheetIdAndAliasIgnoreCase(sheetId, trimmed).isPresent()) {
            throw nameInUse();
        }
        String reach = contactOf(contact);
        if (reach != null && people.existsBySheetIdAndContactAndIdNot(sheetId, reach, id)) {
            throw contactInUse();
        }
        Rollup.Figures before = rollup.of(sheetId);
        person.setName(trimmed);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade);
        }
        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
        person.setTerms(terms);
        boolean contactChanged = !Objects.equals(person.getContact(), reach);
        person.setContact(reach);
        Person edited = save(person);
        audit.recordChangeOnCommit(sheetId, user, entry("PERSON_EDITED", user, edited, edited.gradeOn(today))
                + (termsChanged ? " terms=" + (terms != null ? terms : "") : "")
                + (contactChanged ? " contact=" + (reach != null ? reach : "") : ""));
        rollup.recordChanges(sheetId, user, before);
        return edited;
    }

    /** Retire a person from a date; a missing date takes the sheet's today. They count as retired at once; the live
     *  totals move with it once the sheet's today reaches the date. */
    @Transactional
    public Person retire(String sheetId, String user, long id, LocalDate from) {
        LocalDate today = sheets.load(sheetId, user).getToday();
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        Rollup.Figures before = rollup.of(sheetId);
        person.setRetiredFrom(from != null ? from : today);
        Person retired = save(person);
        audit.recordChangeOnCommit(sheetId, user, "PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + retired.getName() + " from=" + retired.getRetiredFrom());
        rollup.recordChanges(sheetId, user, before);
        return retired;
    }

    /** Put the person on hold from {@code from} (null: the sheet's today) to {@code to} (null: no end), alongside
     *  any holds they have already; the live totals move with it. A to-date before the from-date is refused. */
    @Transactional
    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
        LocalDate today = sheets.load(sheetId, user).getToday();
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        LocalDate start = from != null ? from : today;
        if (to != null && to.isBefore(start)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts");
        }
        Rollup.Figures before = rollup.of(sheetId);
        person.addHold(new Hold(start, to));
        Person saved = save(person);
        audit.recordChangeOnCommit(sheetId, user, "PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " from=" + start);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** Give the person an alias, stored trimmed: refused when blank, or when it is, without regard to case, any
     *  name or alias on the sheet. */
    @Transactional
    public Person addAlias(String sheetId, String user, long id, String alias) {
        sheets.load(sheetId, user);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        String trimmed = alias == null ? "" : alias.trim();
        if (trimmed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An alias cannot be blank");
        }
        if (people.findBySheetIdAndNameOrAliasIgnoreCase(sheetId, trimmed).isPresent()) {
            throw nameInUse();
        }
        person.addAlias(trimmed);
        Person saved = save(person);
        audit.recordChangeOnCommit(sheetId, user, "PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " alias=" + trimmed);
        return saved;
    }

    private static String entry(String event, String user, Person person, String grade) {
        return event + " sheet=" + person.getSheetId() + " by=" + user
                + " name=" + person.getName() + " grade=" + grade;
    }

    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException raced) {
            // Another user took the same name at the same moment: theirs stands.
            throw nameInUse();
        } catch (ObjectOptimisticLockingFailureException raced) {
            // Another user saved the same person at the same moment: theirs stands.
            throw changedSince();
        }
    }

    private static ResponseStatusException changedSince() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved this person since it was opened");
    }

    /** A contact as stored: trimmed and lower-cased; null when blank or not given. */
    private static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) {
            return null;
        }
        return contact.trim().toLowerCase(Locale.ROOT);
    }

    private static ResponseStatusException contactInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on this sheet");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
    }
}
package net.officefloor.hq.app.person;

import org.springframework.format.annotation.DateTimeFormat;
import net.officefloor.hq.app.history.SheetHistory;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.role.RoleService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** People on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** A person as listed: {@code grade} is the one in force on the sheet's today; {@code grades} all those
     *  recorded, in the order they take effect. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, Integer terms,
            long version, boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds, String contact,
            List<String> aliases) {

        public static PersonView of(Person person, LocalDate today) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(GradeView::of).toList(), person.getTerms(), person.getVersion(),
                    person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(HoldView::of).toList(), person.getContact(),
                    person.getAliases());
        }
    }

    /** A grade recorded for a person, in force from {@code from} (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {

        static GradeView of(GradeFrom grade) {
            return new GradeView(grade.getGrade(), grade.getFromDate());
        }
    }

    /** A hold on a person from {@code from} to {@code to}, both inclusive (a null to-date: no end). */
    public record HoldView(LocalDate from, LocalDate to) {

        static HoldView of(Hold hold) {
            return new HoldView(hold.getFromDate(), hold.getToDate());
        }
    }

    /** A hold as the form submits it: a missing from-date takes the sheet's today; a missing to-date has no end. */
    public record HoldForm(LocalDate from, LocalDate to) {
    }

    /** A person's values as the form submits them; the name is stored with surrounding spaces removed; missing
     *  terms: none of their own; the contact is stored trimmed and lower-cased (blank or missing: none). */
    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            @Min(0) @Max(36500) Integer terms,
            @Size(max = 200) String contact) {
    }

    /** An edit of a person: their new values, the date the grade is from (missing: the sheet's today), their own
     *  terms (missing: none), their contact (blank or missing: none) and the version of the person the editor
     *  loaded. */
    public record PersonEdit(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @Min(0) @Max(36500) Integer terms,
            @NotNull Long version,
            @Size(max = 200) String contact) {
    }

    /** An alias as the row submits it; stored trimmed, and refused when blank. */
    public record AliasForm(@Size(max = 200) String alias) {
    }

    /** A retirement: the date the person is retired from; missing takes the sheet's today. */
    public record Retirement(LocalDate from) {
    }

    /** People selected to be given a grade together, from {@code from} (missing: the sheet's today). */
    public record BulkGrade(
            @NotNull @Size(max = 1000) List<@NotNull Long> ids,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate from) {
    }

    /** What a bulk grade did: how many people it changed, and those people as saved, in list order. */
    public record BulkGradeView(int changed, List<PersonView> people) {
    }

    private final PersonService people;
    private final SheetHistory history;
    private final RoleService roles;

    public PersonController(PersonService people, SheetHistory history, RoleService roles) {
        this.people = people;
        this.history = history;
        this.roles = roles;
    }

    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.peopleAsOf(sheetId, asOf);
        }
        LocalDate today = people.today(sheetId);
        return people.list(sheetId).stream().map(p -> PersonView.of(p, today)).toList();
    }

    @PostMapping
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PersonForm request) {
        Person added = people.add(sheetId, user, request.name(), request.grade(), request.terms(),
                request.contact());
        return PersonView.of(added, people.today(sheetId));
    }

    @PutMapping("/{id}")
    public PersonView update(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PersonEdit request) {
        Person edited = people.update(sheetId, user, id, request.version(), request.name(), request.grade(),
                request.gradeFrom(), request.terms(), request.contact());
        return PersonView.of(edited, people.today(sheetId));
    }

    /**
     * Give the selected people a grade together: each, in list order, gets it from the date given as an edit of
     * them in the person form would, keeping their name and terms; one not on the sheet, or saved by someone else
     * meanwhile, is skipped.
     */
    @PostMapping("/bulk-grade")
    public BulkGradeView bulkGrade(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody BulkGrade request) {
        if (roles.isViewer(sheetId, user)) {
            // A viewer's bulk action goes through with nothing done: no selected person is changed.
            return new BulkGradeView(0, List.of());
        }
        Set<Long> selected = new HashSet<>(request.ids());
        List<PersonView> changed = new ArrayList<>();
        for (Person person : people.list(sheetId)) {
            if (selected.contains(person.getId())) {
                try {
                    Person edited = people.update(sheetId, user, person.getId(), person.getVersion(),
                            person.getName(), request.grade(), request.from(), person.getTerms());
                    changed.add(PersonView.of(edited, people.today(sheetId)));
                } catch (ResponseStatusException refusal) {
                    // Saved by someone else meanwhile: theirs stands, and this person is not changed.
                }
            }
        }
        return new BulkGradeView(changed.size(), changed);
    }

    @PostMapping("/{id}/retire")
    public PersonView retire(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody Retirement request) {
        return PersonView.of(people.retire(sheetId, user, id, request.from()), people.today(sheetId));
    }

    /** Give the person an alias. */
    @PostMapping("/{id}/aliases")
    public PersonView addAlias(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody AliasForm request) {
        return PersonView.of(people.addAlias(sheetId, user, id, request.alias()), people.today(sheetId));
    }

    /** Put the person on hold over the dates given, alongside any holds they already have. */
    @PostMapping("/{id}/hold")
    public PersonView hold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody HoldForm request) {
        return PersonView.of(people.hold(sheetId, user, id, request.from(), request.to()), people.today(sheetId));
    }
}

