import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The patrons people name on a sheet. */
@Service
public class PatronService {

    private final PatronRepository patrons;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PatronService(PatronRepository patrons, PersonRepository people, SheetService sheets, Audit audit) {
        this.patrons = patrons;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Every patron named on the sheet, in the order they were named. */
    @Transactional(readOnly = true)
    public List<Patron> list(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Name another person on the sheet as the person's patron: never themselves, and never the same one twice. */
    @Transactional
    public Patron add(String sheetId, String user, long personId, long patronId) {
        sheets.load(sheetId, user);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet"));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be their own patron");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw alreadyPatron();
        }
        Patron added;
        try {
            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException raced) {
            // Another user named the same patron at the same moment: theirs stands.
            throw alreadyPatron();
        }
        audit.recordChangeOnCommit(sheetId, user, "PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " patron=" + patron.getName());
        return added;
    }

    private static ResponseStatusException alreadyPatron() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron");
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The roles a sheet's settings assign to user names. */
@Service
public class RoleService {

    private final RoleRepository roles;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Delegations delegations;
    private final Audit audit;

    public RoleService(RoleRepository roles, SheetService sheets, SheetRepository sheetStore, Delegations delegations,
            Audit audit) {
        this.roles = roles;
        this.delegations = delegations;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<Role> list(String sheetId) {
        return roles.findBySheetIdOrderByUserName(sheetId);
    }

    /** The role a user name acts in on the sheet: steward while a delegation of the role to it holds the sheet's
     *  today, else the one assigned. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        if (delegations.actingFor(sheetId, userName).isPresent()) {
            return Role.STEWARD;
        }
        return assignedRoleOf(sheetId, userName);
    }

    /** The role assigned to a user name on the sheet, else clerk; a delegation does not change it. */
    @Transactional(readOnly = true)
    public String assignedRoleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /** Whether a user name is a viewer on the sheet: one who sees everything and can change nothing. */
    @Transactional(readOnly = true)
    public boolean isViewer(String sheetId, String userName) {
        return Role.VIEWER.equals(roleOf(sheetId, userName));
    }

    /** Assign a role (clerk, steward or viewer) to a user name, replacing the one it had. The sheet is locked
     *  first, so two assignments to one name are made one at a time. */
    @Transactional
    public Role set(String sheetId, String user, String userName, String role) {
        sheets.load(sheetId, user);
        sheetStore.findLockedById(sheetId).orElseThrow();
        Role row = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new Role(sheetId, userName, role));
        row.setRole(role);
        Role saved = roles.saveAndFlush(row);
        audit.recordChangeOnCommit(sheetId, user, "ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + saved.getUserName() + " role=" + saved.getRole());
        return saved;
    }
}
