8:import { PatronView, Patrons } from '../../core/patrons';
231:            — aliases <span data-testid="person-aliases">{{ (p.aliases ?? []).join(', ') }}</span>
232:            <label [attr.for]="'person-alias-input-' + p.id">Alias</label>
233:            <input [id]="'person-alias-input-' + p.id" data-testid="person-alias-input" #aliasInput autocomplete="off"
235:            <button type="button" data-testid="person-alias-add" (click)="addAlias(p, aliasInput)"
236:                    [disabled]="aliasing() === p.id" [attr.aria-label]="'Add an alias of ' + p.name">Add alias</button>
284:            — patrons <span data-testid="person-patrons">{{ patronsOf(p.id) }}</span>
286:            <label [attr.for]="'person-patron-select-' + p.id">Patron</label>
287:            <select [id]="'person-patron-select-' + p.id" data-testid="person-patron-select" #patronSelect
288:                    (change)="patronError.set(null)">
293:            <button type="button" data-testid="person-patron-add" (click)="addPatron(p, patronSelect.value)"
294:                    [disabled]="addingPatron() === p.id" [attr.aria-label]="'Add a patron of ' + p.name">Add patron</button>
298:            @if (patronError()?.id === p.id) {
299:              <p role="alert" data-testid="person-patron-error">{{ patronError()?.message }}</p>
301:            @if (personError()?.id === p.id) {
302:              <p role="alert" data-testid="person-error">{{ personError()?.message }}</p>
319:  private readonly patronsApi = inject(Patrons);
371:  /** Every patron named on the sheet. */
372:  private readonly patrons = signal<PatronView[]>([]);
373:  /** The person a patron is being added to, so a second press waits for the first. */
